results = []


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}")


NAV = {"type": "navigation", "description": "Go to the bench", "completion_criteria": "At the bench", "target": "the bench"}
PICK = {"type": "manipulation", "description": "Pick up the beaker", "completion_criteria": "The beaker is held", "target": None}
PLACE = {"type": "manipulation", "description": "Place the beaker on the hotplate", "completion_criteria": "The beaker is on the hotplate and the gripper is released", "target": None}
LABELS = {"labels": [{"index": 0, "primitive": "pick", "objects": [{"phrase": "the beaker", "role": "manipulated"}]}]}


def make_plan(segments):
    labels, k = [], 0
    for i, s in enumerate(segments):
        if s["type"] == "manipulation":
            prim = "pick" if "Pick" in s["description"] else "place"
            objs = [{"phrase": "the beaker", "role": "manipulated"}] + ([{"phrase": "the hotplate", "role": "destination"}] if prim == "place" else [])
            labels.append({"index": i, "primitive": prim, "objects": objs})
    return postprocess({"task_name": "t", "segments": segments}, make_stored_labeler({"labels": labels}), say=lambda *_: None)


class World:
    """A world model whose refreshes are counted; the beaker's state is set by the tests."""

    def __init__(self, held_by=None, axis=(0.0, 0.0, 1.0)):
        self.w = WorldModel()
        self.refreshes = 0
        self.held_by, self.axis = held_by, np.array(axis, float)
        self.w.sources.append(self.source)
        self.w.refresh(0.0)

    def source(self, world, t):
        self.refreshes += 1
        world.upsert(Entry("beaker", "beaker", ("beaker",), "object", np.zeros(3), self.axis, {"contents": "empty", "held_by": self.held_by, "height": 0.1}))
        world.upsert(Entry("hotplate", "hotplate", ("hotplate",), "fixture", np.array([0.3, 0, 0.0]), None, {}))


class Nav:
    """A navigation module that finishes after three steps, or fails."""

    def __init__(self, fail=False):
        self.n, self.fail, self.started = 0, fail, []

    def module(self):
        return {"name": "nav", "start": lambda seg: (self.started.append(seg), setattr(self, "n", 0)), "step": self.step, "done": lambda: self.n >= 3 and not self.fail,
                "error": lambda: "navigation: blocked" if self.fail and self.n >= 2 else None, "phase": lambda: "NAVPH", "events": lambda: [], "resume": lambda: None, "report": lambda: {}}

    def step(self, o):
        self.n += 1
        return {"nav": 1}


class Manip:
    """A manipulation module: each attempt takes three steps and reports its gripper event on the first; attempts in `fail_on` fail on the second step with `msg`; recover() takes two steps."""

    def __init__(self, world, fail_on=(), msg="the arm did not settle", error_kind=None, on_fail=None, recover_fails=False, with_recover=True):
        self.world, self.fail_on, self.msg, self.kind, self.on_fail, self.recover_fails = world, set(fail_on), msg, error_kind, on_fail, recover_fails
        self.attempt, self.n, self.err, self.recovering, self.rec_n, self.recovers, self.starts, self.side = 0, 0, None, False, 0, 0, [], "left"
        self.with_recover = with_recover
        self.prim = None
        self.miss_on = set()                                 # attempts whose pick closes on nothing (the beaker stays out of the hand)

    def module(self):
        m = {"name": "manip", "start": self.start, "step": self.step, "done": self.done, "error": self.error, "phase": lambda: "MPH", "events": self.events, "resume": lambda: None,
             "report": lambda: {}, "side": "left", "error_kind": lambda: self.kind if self.err else None}
        if self.with_recover:
            m["recover"] = self.recover
        return m

    def start(self, seg):
        self.starts.append(seg)
        self.attempt += 1
        self.n, self.err, self.recovering, self.prim = 0, None, False, seg["primitive"]

    def recover(self):
        self.recovering, self.rec_n, self.err = True, 0, None
        self.recovers += 1

    def step(self, o):
        if self.recovering:
            self.rec_n += 1
            if self.recover_fails and self.rec_n == 2:
                self.err = "recovery: mink found no solution"
            return {"recover": 1}
        self.n += 1
        if self.attempt in self.fail_on and self.n == 1:
            self.err = self.msg
            if self.on_fail:
                self.on_fail()
        return {"cmd": 1}

    def events(self):
        if self.n == 1 and not self.recovering and self.prim and self.err is None:
            self.world.held_by = ("left" if self.attempt not in self.miss_on else None) if self.prim == "pick" else None    # the pick's close puts the beaker in the hand, the place's open takes it out
            return ["gripper_closed" if self.prim == "pick" else "gripper_opened"]
        return []

    def done(self):
        return self.rec_n >= 2 if self.recovering else (self.n >= 3 and self.err is None)

    def error(self):
        return self.err


def checker(fail_checks=()):
    """A checker (the oracle's name, so the verdict is the oracle's too) that fails the deciding checks numbered in fail_checks (1, 2, ...)."""
    calls = []

    def chk(seg, ev, obs, decides=False):
        if decides:
            calls.append(seg["description"])
        n = len(calls)
        ok = not (decides and n in fail_checks)
        return {"passed": ok, "reason": "" if ok else "the beaker is not held", "details": {}}
    return {"name": "sim oracle", "check": chk, "calls": calls}


def run(segments, manip_kw=None, world_kw=None, operator=None, fail_checks=(), cfg=None, nav_fail=False, ticks=200):
    world = World(**(world_kw or {}))
    manip = Manip(world, **(manip_kw or {}))
    nav = Nav(nav_fail)
    ck = checker(fail_checks)
    modules = {"navigation": nav.module(), "manipulation": manip.module(), "checker": ck, "world": world.w, "grounder": make_grounder(world.w, operator=operator)}
    if operator is not None:
        modules["operator"] = operator
    orch = make_orchestrator(make_plan(segments), modules, cfg)
    for k in range(ticks):
        orch["step"]({"time": 0.01 * k})
        if orch["state"]["finished"] or orch["state"]["failure"]:
            break
    return orch, manip, world, ck, nav


def attempts(orch, i=None):
    return [(a["segment"], a["attempt"], a["outcome"]) for a in orch["state"]["attempts"] if i is None or a["segment"] == i]


def main():
    print("1. retry then success")
    orch, manip, world, ck, _ = run([PICK], {"fail_on": [1]})
    st = orch["state"]
    check("a failed step is retried once: recover() called once, the skill started twice, the plan finishes", st["finished"] and not st["failure"] and manip.recovers == 1 and manip.attempt == 2, f"{attempts(orch)}")
    check("the objects were grounded again and the world model refreshed for the retry", len(st["grounded"]) == 2 and world.refreshes >= 4, f"grounded {len(st['grounded'])}, refreshes {world.refreshes}")
    check("every attempt is logged: attempt 1 failed with its reason, attempt 2 done; the decision of the first is 'retry'", attempts(orch) == [(0, 1, "failed"), (0, 2, "done")]
          and st["attempts"][0]["reason"] == "the arm did not settle" and st["attempts"][0]["decision"] == "retry")
    world = World()
