    manip.miss_on = {1}
    ck = checker([1])
    orch = make_orchestrator(make_plan([PICK]), {"navigation": Nav().module(), "manipulation": manip.module(), "checker": ck, "world": world.w, "grounder": make_grounder(world.w)})
    for k in range(200):
        orch["step"]({"time": 0.01 * k})
